const root=path.dirname(path.dirname(fileURLToPath(import.meta.url))),at=process.argv.indexOf('--out');assert.ok(at>=0);const out=path.resolve(process.argv[at+1]),site=path.join(out,'site'),before=path.join(out,'previous-v15/site');
