const c=json('learning/course.v16.json'),p=json('learning/course.v15.json',before),m=json('data/library.json'),report=JSON.parse(fs.readFileSync(path.join(out,'evidence/build.json')));
const packs=Object.fromEntries(Object.keys(m.entries).map(b=>[b,json(m.entries[b].path)])),lines=new Map(),units=new Map();for(const [b,pack] of Object.entries(packs))for(const u of pack.units){units.set(b+'|'+u.id,u);for(const l of u.lines)lines.set(b+'|'+l.id,l);}
const target=packs.jaap.units.slice(105,120),newNotes=Object.keys(c.closeTextNotes).filter(k=>!Object.hasOwn(p.closeTextNotes,k)),newStudies=Object.keys(c.unitLessons).filter(k=>!Object.hasOwn(p.unitLessons,k));
