check('Exact V15 and all fifteen previous course bytes preserved',()=>{assert.equal(sha(raw('learning/course.v15.json')),'f9c1148a943f0530c9df39be5d3875f930109817468d23f44ab5391e6a8b87d8');for(let i=1;i<=15;i++)assert.ok(raw(`learning/course.v${i}.json`).equals(raw(`learning/course.v${i}.json`,before)));});
check('Frozen manifest and six original source packs preserve hashes, records and review flags',()=>{assert.equal(sha(raw('data/library.json')),'b5865b293acc3ea91a20487dd82efd6f503d22dc5823bc2a67effcd146840d7a');assert.equal(lines.size,1361);assert.equal(units.size,327);for(const [b,e] of Object.entries(m.entries)){assert.equal(sha(raw(e.path)),e.sha256);assert.equal(packs[b].humanCollationApproved,false);assert.equal(packs[b].rightsCleared,false);for(const u of packs[b].units)for(const l of u.lines)assert.equal(sha(l.text),l.sha256);}});
check('979 prior notes and 232 prior Study objects remain exact',()=>{assert.equal(Object.keys(p.closeTextNotes).length,979);assert.equal(Object.keys(p.unitLessons).length,232);for(const [k,v] of Object.entries(p.closeTextNotes))assert.deepEqual(c.closeTextNotes[k],v);for(const [k,v] of Object.entries(p.unitLessons))assert.deepEqual(c.unitLessons[k],v);for(const k of ['editorialAmendments','sourceReuseEvidence','candidateV15Reuse'])assert.deepEqual(c[k],p[k]);});
check('The increment is precisely Chhands 106–120: 60 records, 15 studies, no added headings',()=>{assert.deepEqual(target.map(u=>u.id),Array.from({length:15},(_,i)=>'jaap'+(106+i)));assert.ok(target.every(u=>u.lines.length===4&&u.metricalHeadings.length===0));assert.deepEqual(keys(newNotes),keys(target.flatMap(u=>u.lines.map(l=>'jaap|'+l.id))));assert.deepEqual(keys(newStudies),keys(target.map(u=>'jaap|'+u.id)));});
check('New notes are bilingual, unique source occurrences and explicitly unreviewed',()=>{for(const k of newNotes){const n=c.closeTextNotes[k],l=lines.get(k);assert.equal(n.lineId,l.id);assert.equal(n.sourceSha256,l.sha256);assert.equal(l.held,false);assert.equal(n.status,'DRAFT_AI_UNREVIEWED');assert.equal(n.kind,'SELECTIVE_EDUCATIONAL_PARAPHRASE_NOT_LITERAL_TRANSLATION');assert.ok(n.simpleEn.length>8&&n.interpretiveCaution.length>40);assert.match(n.simplePa,/\p{Script=Gurmukhi}/u);for(const s of [n.simpleEn,n.simplePa,n.interpretiveCaution])assert.ok(!/[\uFFFD\uE000-\uF8FF]/u.test(s));}});
check('Each new Study has all established fields and vocabulary from its own source',()=>{for(const k of newStudies){const l=c.unitLessons[k],u=units.get(k),s=l.study;assert.equal(l.status,'DRAFT_AI_UNREVIEWED');assert.deepEqual(l.sourceAnchor,{id:u.lines[0].id,sha256:u.lines[0].sha256});assert.ok(l.simple.en.length>35);assert.match(l.simple.pa,/\p{Script=Gurmukhi}/u);assert.ok(s.closeReading.length>400);for(const f of ['focus','interpretationCare','reflection','teachBack'])assert.ok(s[f].length>15);assert.ok(s.words.length>=3);for(const v of s.words){assert.ok(u.lines.some(x=>x.text.includes(v.gurmukhi)));assert.equal(v.status,'WORKING_GLOSS_NOT_APPROVED');}}});
check('Five exact repeated lines reuse main wording without changing source counters',()=>{assert.equal(c.candidateV16Reuse.length,5);const norm=t=>t.replace(/॥[੦-੯]+॥$/u,'॥');for(const r of c.candidateV16Reuse){assert.equal(r.origin,'EARLIER_IN_V16');assert.equal(norm(lines.get(r.from).text),norm(lines.get(r.to).text));for(const f of ['simpleEn','simplePa'])assert.equal(c.closeTextNotes[r.from][f],c.closeTextNotes[r.to][f]);}assert.equal(c.coverage.accounting.newJaapLineDrafts,55);assert.equal(c.coverage.accounting.withinBatchMainReuses,5);});
check('Coverage independently reconciles to 1039 records,247 studies and Jaap466/120',()=>{assert.equal(Object.keys(c.closeTextNotes).length,1039);assert.equal(Object.keys(c.unitLessons).length,247);assert.equal(c.coverage.closeTextOccurrenceNotes,1039);assert.equal(c.coverage.writtenUnitLessons,247);for(const b of Object.keys(m.entries)){const x=c.coverage.byBani[b];assert.equal(x.firstLineNotes,Object.keys(c.closeTextNotes).filter(k=>k.startsWith(b+'|')).length);assert.equal(x.draftLessons,Object.keys(c.unitLessons).filter(k=>k.startsWith(b+'|')).length);if(b!=='jaap')assert.deepEqual(x,p.coverage.byBani[b]);}assert.equal(c.coverage.byBani.jaap.firstLineNotes,466);assert.equal(c.coverage.byBani.jaap.draftLessons,120);});
check('Anand24 remains wholly withheld and Jaap121 onward stays pending',()=>{const h=units.get('anand|anand24');assert.equal(h.lines.length,6);assert.ok(!c.unitLessons['anand|anand24']);for(const l of h.lines)assert.ok(!c.closeTextNotes['anand|'+l.id]);assert.ok(h.lines.some(l=>l.held&&l.text.includes('\uF03D')));for(const u of packs.jaap.units.slice(120)){assert.ok(!c.unitLessons['jaap|'+u.id]);for(const l of u.lines)assert.ok(!c.closeTextNotes['jaap|'+l.id]);}});
check('References are additive; uncertainty and authority boundaries remain explicit',()=>{for(const f of ['editorialStatus','reviewer','rightsStatus','publicationAllowed','sourceOriginalUnchanged','boundManifestSHA256','baseSourceCommit'])assert.deepEqual(c.meta[f],p.meta[f]);assert.equal(c.coverage.reviewedSourceMeaningLines,0);assert.equal(c.coverage.reviewedUnitLessons,0);assert.deepEqual(c.meta.references.slice(0,p.meta.references.length),p.meta.references);assert.deepEqual(c.sourceChecks.slice(0,p.sourceChecks.length),p.sourceChecks);assert.equal(new Set(c.meta.references.map(x=>x.key)).size,c.meta.references.length);for(const x of c.sourceChecks.slice(p.sourceChecks.length))assert.equal(x.humanReviewed,false);assert.match(c.closeTextNotes['jaap|jaap113.line01'].interpretiveCaution,/dharam/);assert.match(c.closeTextNotes['jaap|jaap120.line01'].interpretiveCaution,/power/);});
class E{constructor(t){this.tagName=t.toUpperCase();this.className='';this.dataset={};this.attributes={};this.children=[];this.value='';}set textContent(v){this.value=String(v);this.children=[];}get textContent(){return this.value+this.children.map(x=>typeof x==='string'?x:x.textContent).join('');}append(...x){this.children.push(...x);}replaceChildren(...x){this.value='';this.children=x;}setAttribute(k,v){this.attributes[k]=String(v);}getAttribute(k){return this.attributes[k]??null;}}
check('The real renderer exposes new meanings and studies; Read stays clear and wrong hashes fail closed',()=>{const window={};vm.runInNewContext(raw('learning/learning-ui.js').toString(),{window,document:{createElement:t=>new E(t)}});const ui=window.GLP_NitnemLearning;for(const u of target){assert.equal(ui.unitLesson(c,'jaap',u,'read','continuous'),null);const v=ui.unitLesson(c,'jaap',u,'study','passage');assert.ok(v.textContent.includes(c.unitLessons['jaap|'+u.id].study.closeReading)&&v.textContent.includes('HUMAN REVIEW PENDING'));for(const l of u.lines){const n=c.closeTextNotes['jaap|'+l.id],x=ui.lineNote(c,'jaap',l);assert.ok(x.textContent.includes(n.simpleEn)&&x.textContent.includes(n.simplePa));assert.ok(ui.lineDetails(c,'jaap',l,u).textContent.includes(n.interpretiveCaution));assert.equal(ui.lineNote(c,'jaap',{...l,sha256:'0'.repeat(64)}),null);}}});
check('V15 theme-jump repair and all saved-learning/appearance bytes are preserved',()=>{let reader=raw('reader.js').toString();assert.equal(reader.split("document.querySelectorAll('button[data-mode]')").length,3);reader=reader.replace(sha(raw('learning/course.v16.json')),sha(raw('learning/course.v15.json'))).replace("jsonBytes('learning/course.v16.json',EXPECTED_LEARNING)","jsonBytes('learning/course.v15.json',EXPECTED_LEARNING)");assert.equal(reader,raw('reader.js',before).toString());for(const f of ['appearance.js','appearance.css','index.html','reader.css','japji.html','japji-assets/js/japji-full.js','japji-assets/js/shared-learning.js','learning/learning-ui.js','continuous-core.js'])assert.ok(raw(f).equals(raw(f,before)),f);assert.match(raw('index.html').toString(),/id="pace"[^>]*max="200"/);});
